{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "FTY720-C2, the N-acetyl analogue of FTY720 and the closest retrieved structure, rapidly entered mouse brain after IV or oral dosing and achieved brain concentrations much higher than plasma, demonstrating robust CNS access for the amide-modified FTY720 core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "FTY720 itself showed brain-to-blood ratios greater than 10 and high CNS accumulation in mice, supporting strong BBB penetration for the octylphenyl-propanediol scaffold shared by the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "MitoQ, a decyltriphenylphosphonium conjugate, was detected at high levels in mouse brain tissue, showing that a bulky lipophilic triphenylphosphonium cation can cross the BBB despite its permanent positive charge.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "FTY720-P, the charged phosphate metabolite of FTY720, was reported to accumulate in human brain, indicating that polar/charged modifications of this scaffold do not necessarily prevent CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A related long-chain amide diol (HPA-12) showed measurable brain uptake and retention after perfusion in mice, supporting CNS penetration for amide-containing lipophilic diols analogous to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an amide-linked triphenylphosphonium conjugate of the FTY720 scaffold. The closest analogue, N-acetyl FTY720, shows rapid and high brain exposure in mice; FTY720 and FTY720-P also accumulate in CNS; and a separate triphenylphosphonium conjugate (MitoQ) penetrates brain tissue. These convergent supportive data outweigh low-similarity negative controls, so the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct in vivo brain concentration or brain-to-plasma ratio measurement for the exact query molecule.",
    "The impact of the triphenylphosphonium propionamide moiety on transporter-mediated efflux (P-gp/BCRP) is not directly measured.",
    "Unbound brain concentrations and pharmacologically active CNS exposure are not quantified."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C02"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "FTY720 amide analogues"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C07", "C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "FTY720 and phosphorylated metabolite"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C14"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "triphenylphosphonium conjugates"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C05"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "long-chain amide diols"
    },
    {
      "applicability": "low",
      "card_ids": ["C13"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "phenylbutyric acid negatives"
    }
  ],
  "revision_action": "initial"
}

